      raceEngineer2: { name: 彼得·博宁顿, skill: 88, abilities: { setup: 90, communication: 91, reaction: 88, weather: 86 }, salary: 1.2 }
      pitCrew: { skill: 86, salary: 1.6 }
      strategist: { name: 罗茜·韦特, skill: 87, abilities: { strategy: 89, weather: 87, reaction: 86, risk: 67 }, salary: 1.1 }
    carBase: { perf: 87, rel: 88 }
    parts:
      power_unit: { perf: 91, rel: 87 }
      ers: { perf: 86, rel: 85 }
      gearbox: { perf: 87, rel: 89 }
      chassis: { perf: 88, rel: 88 }
      front_wing: { perf: 87, rel: 89 }
      rear_wing: { perf: 87, rel: 89 }
      floor: { perf: 88, rel: 87 }
      sidepods: { perf: 87, rel: 89 }
