    principal: 安德里亚·斯特拉
    engine: 梅赛德斯
    base: 英国·沃金
    funds: 115
    sponsorIncome: 7.4
    operatingCost: 2.6
    targetPosition: 1
    facilities: { windTunnel: 5, cfd: 5, simulator: 5, factory: 5 }
    staff:
