      raceEngineer: { name: 威尔·约瑟夫, skill: 84, abilities: { setup: 85, communication: 87, reaction: 83, weather: 82 }, salary: 1.1 }
      raceEngineer2: { name: 汤姆·斯托拉德, skill: 85, abilities: { setup: 86, communication: 85, reaction: 86, weather: 84 }, salary: 1.1 }
