    parts:
      # 钢制气缸盖方案被放弃，退回成熟方案：功率接近梅赛德斯，可靠性略逊
      power_unit: { perf: 89, rel: 84 }
      ers: { perf: 85, rel: 83 }
      gearbox: { perf: 79.1, rel: 84 }
      chassis: { perf: 81.1, rel: 85 }
      front_wing: { perf: 82.1, rel: 85 }
      rear_wing: { perf: 82.1, rel: 84 }
      floor: { perf: 80.1, rel: 83 }
      sidepods: { perf: 79.1, rel: 85 }
      suspension: { perf: 81.1, rel: 85 }
